svg.script:
//
    const CONFIG = {
        g3: {
            center: [136.36, 148.74], // Initial guess of center
            translate: [0, 0],        // Original translation
            rpm: 160                  // Rotation speed in RPM
        },
        g4081: {
            center: [534.595, 214.175],       // Initial guess of center for g999
            translate: [0, 0],      // Original translation for g999
            rpm: -430                   // Rotation speed in RPM for g999
        }
    };

    (function animate() {
        // Iterate over all items in CONFIG
        for (const [id, config] of Object.entries(CONFIG)) {
            const { center, translate, rpm } = config;

            // Calculate the rotation angle based on current time
            const angle = (Date.now() / 60000) * rpm * 360 % 360;

            // Update the transform attribute for the element with the current ID
            const element = document.getElementById(id);
            if (element) {
                element.setAttribute(
                    'transform',
                    `translate(${translate.join(',')}) rotate(${angle}, ${center.join(',')})`
                );
            }
        }

        // Schedule the next animation frame
        requestAnimationFrame(animate);
    })();
//
